        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)

    # Track variable occurrences
    # For each variable, store (clause_index, literal_sign)
    var_occurrences = [[] for _ in range(m + 1)]

    for clause_idx, literals in enumerate(clauses):
        for lit in literals:
            var = abs(lit)
            var_occurrences[var].append((clause_idx, 1 if lit > 0 else -1))

    # If any variable appears more than 2 times, problem constraint is violated
    # But we'll trust the problem statement. Handle up to 2 occurrences.

    # Build clause to variable map
    # For efficient checking
    assignment = [0] * (m + 1)  # 1-based, 0 = unassigned, 1 = True, -1 = False

    # Check if a literal is satisfied
    def is_lit_satisfied(lit):
        var = abs(lit)
        sign = 1 if lit > 0 else -1
        if assignment[var] == 0:  # unassigned
            return True  # can be satisfied
        return assignment[var] * sign > 0  # returns True if same sign

    # Check if a clause is satisfied or has conflict
    def check_clause(literals):
        for lit in literals:
            if is_lit_satisfied(lit):
                return True
        return False

    # Iteratively assign variables that appear in unsatisfied clauses
    changed = True
    while changed:
        changed = False
        assigned = False

        for clause_idx, literals in enumerate(clauses):
            if not check_clause(literals):
                # Clause not satisfied, need to assign something
                found = False
                for lit in literals:
                    var = abs(lit)
                    if assignment[var] == 0:
                        # Unassigned variable, assign to satisfy this clause
                        lit_sign = 1 if lit > 0 else -1
                        assignment[var] = lit_sign
                        changed = True
                        assigned = True
                        break
                if found:
                    continue
                # All variables in clause are assigned and don't satisfy it
                if not check_clause(literals):
                    return 'NO'
        # If no changes and we haven't assigned everything, and all clauses are satisfied
        if not changed:
            break

    # Check if all clauses are satisfied
    for literals in clauses:
        if not check_clause(literals):
            return 'NO'

    # Convert assignment to output format
    result = ''.join(str(assignment[i]) for i in range(1, m + 1))

    return 'YES\n' + result


