    # Edge (u, v) with weight w: include if w - (cost of u, v) is beneficial in context
    # 
    # Model: Source S, Sink T
    # Vertex i: edge S->i with capacity a[i-1]
    # Edge (u,v) with weight w: this must be represented properly

    # Correct model:
    # Create a node for each edge
    # Edge node e connects to source with capacity w (benefit of edge)
    # Edge node e connects to both endpoints u and v with capacity INF
    # Each vertex connects to sink with capacity a[i-1] (cost of vertex)
    # 
    # Min cut gives us the minimum "loss", so max gain = sum(w) - min_cut

    # Build the correct flow network
    # Source S=0, Edge nodes n+1..n+m, Vertex nodes 1..n, Sink T=n+m+1

    # Actually for simplicity and since n,m <= 1000, I can use this construction:

    S = 0
    T = n + m + 1

    # Clear and rebuild capacity
    capacity = {}
    def add_edge(u, v, cap):
        if u not in capacity:
            capacity[u] = {}
        if v not in capacity:
            capacity[v] = {}
        if v not in capacity[u]:
            capacity[u][v] = 0
        capacity[u][v] += cap
        if u not in capacity[v]:
            capacity[v][u] = 0
        capacity[v][u] -= cap  # residual

    # Vertex nodes: 1..n
    # Edge nodes: n+1..n+m (0-indexed as n+i for i in 0..m-1)

    INF = 10**15

    # For each vertex i: connect to Sink with capacity a[i-1]
    # This represents the cost of including vertex i
    for i in range(1, n + 1):
        add_edge(i, T, a[i - 1])

    # For each edge j (connecting u, v with weight w):
    #   Create edge node n+j (1-indexed edge nodes start from n+1)
    #   Edge node -> Source with capacity w (benefit from selecting this edge)
    #   Edge node -> Vertex u with INF
    #   Edge node -> Vertex v with INF
    for j, (u, v, w) in enumerate(edges):
        edge_node = n + j + 1  # 1-indexed
        add_edge(S, edge_node, w)
        add_edge(edge_node, u, INF)
        add_edge(edge_node, v, INF)

    # Calculate max flow from source to sink
    flow = dinic()

    # Maximum subgraph weight = sum of all edge weights - max_flow (which is min cut)
    result = total_edge_weight - flow

    # The result could be negative if best is empty subgraph with weight 0
    return str(max(0, result))

# Helper function for Dinic's algorithm (declared but needs to be accessible)
def bfs(capacity, S, T):
    visited = {S}
    parent = {S: None}
    queue = [S]
    while queue:
        u = queue.pop(0)
        if u == T:
            return parent
        for v, cap in capacity.get(u, {}).items():
            if cap > 0 and v not in visited:
                visited.add(v)
                parent[v] = u
                queue.append(v)
    return None

def dinic(capacity, S, T):
    from sys import maxsize
    INF = maxsize

    def bfs():
        visited = {S}
        parent = {S: None}
        queue = [S]
        while queue:
            u = queue.pop(0)
            if u == T:
                return parent
            for v, cap in capacity.get(u, {}).items():
                if cap > 0 and v not in visited:
                    visited.add(v)
                    parent[v] = u
                    queue.append(v)
        return None

    def dfs(u, f, parent):
        if u == T:
            return f
        visited.add(u)
        for v in capacity.get(u, keys()):
            if capacity[u][v] > 0 and v not in visited and v in parent:
                flow = dfs(v, min(f, capacity[u][v]), parent)
                if flow > 0:
                    capacity[u][v] -= flow
                    capacity[v][u] += flow
                    return flow
        return 0

    max_flow = 0
    visited = set()
    while True:
        parent = bfs()
        if parent is None:
            break
        while True:
            flow = dfs(S, INF, parent)
            if flow == 0:
                break
            max_flow += flow

    return max_flow
