            continue
        parts = line.strip().split()
        if parts[0] == '1':
            if current_interval:
                intervals.append(current_interval)
                current_interval = []
        else:
            current_interval.append(parts[1])
    if current_interval:
        intervals.append(current_interval)

    # Collect all unique friends
    friend_set = set()
    for interval in intervals:
        friend_set.update(interval)

    friend_list = sorted(list(friend_set))
    name_to_idx = {name: i for i, name in enumerate(friend_list)}
    k = len(friend_list)

    if k == 0:
        return '0'

    # Build conflict graph using bitmask
    adj_mask = [0] * k

    for interval in intervals:
        n_in_interval = len(interval)
        present = [name_to_idx[x] for x in interval]

        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                u, v = present[i], present[j]
                adj_mask[u] |= (1 << v)
                adj_mask[v] |= (1 << u)

    best = [0]

    def solve(available_mask, count):
        if count + bin(available_mask).count('1') <= best[0]:
            return

        if available_mask == 0:
            best[0] = max(best[0], count)
            return

        # Find any available bit
        t = (available_mask & -available_mask).bit_length() - 1

        # Try branch 1: don't pick node t, remove t from available and recurse
        new_available_no = available_mask & ~((1 << t))
        solve(new_available_no, count)

        # Try branch 2: pick node t, remove t and its conflicts
        new_available_yes = available_mask & ~(adj_mask[t] | (1 << t))
        if new_available_yes < available_mask:  # ensure we reduced the mask
            solve(new_available_yes, count + 1)

    solve((1 << k) - 1, 0)

    return str(best[0])
