Looking at this problem, I need to track which values of bananas (0 to m) are reachable at each timestep, and find the earliest timestep for each value.

Key insights:
1. At each timestep, we start with previously reachable values and apply the operation 0 to y times
2. Type 1 adds ⌈x⌉ repeatedly; Type 2 multiplies by x and takes ceiling
3. We track the earliest timestep each value j (1 to m) is reachable
4. Values can grow beyond m, so we stop tracking those

```python
import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        t, x_prime, y = map(int, lines[i].split())
        x = x_prime / 100000.0
        operations.append((t, x, y))

    # earliest[j] stores the earliest timestep to reach value j, -1 means not reached
    earliest = [-1] * (m + 1)
    earliest[0] = 0

    # reachable contains all values we can reach before current timestep
    reachable = {0}

    for i in range(n):
        t, x, y = operations[i]
        time = i + 1

        new_reachable = set()

        if t == 1:
            # Type 1: k := ceil(k + x), repeat a times (0 <= a <= y)
            c = math.ceil(x)
            for prev in reachable:
                if prev > m:
                    continue
                cur = prev
                for a in range(y + 1):
                    if cur > m:
                        break
                    new_reachable.add(cur)
                    cur += c
        else:
            # Type 2: k := ceil(k * x), repeat a times (0 <= a <= y)
            for prev in reachable:
                if prev > m:
                    continue
                cur = prev
                for a in range(y + 1):
                    if cur > m:
                        break
                    new_reachable.add(cur)
                    cur = math.ceil(cur * x)

        reachable = new_reachable

        # Update earliest time for each newly reached value
        for v in reachable:
            if v > 0 and earliest[v] == -1:
                earliest[v] = time

    # Format output
    result = []
    for j in range(1, m + 1):
        result.append(str(earliest[j]))

    return ' '.join(result)
