import sys
from collections import deque

def dinic_max_flow(n_edges, num_nodes):
    INF = float('inf')
    graph = [[] for _ in range(num_nodes)]

    class Edge:
        def __init__(self, to, cap):
            self.to = to
            self.cap = cap
            self.flow = 0

        def residual(self):
            return self.cap - self.flow

    def add_edge(u, v, cap):
        graph[u].append(Edge(v, cap))
        graph[v].append(Edge(u, 0))

    def bfs(s, t):
        nonlocal graph
        level = [-1] * num_nodes
        level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for e in graph[u]:
                if e.residual() > 0 and level[e.to] == -1:
                    level[e.to] = level[u] + 1
                    q.append(e.to)
        return level

    def dfs(u, t, f, ptr, level):
        if f == 0:
            return 0
        if u == t:
            return f
        for i in range(ptr[u], len(graph[u])):
            ptr[u] = i
            e = graph[u][i]
            if e.residual() > 0 and level[e.to] == level[u] + 1:
                pushed = dfs(e.to, t, min(f, e.residual()), ptr, level)
                if pushed > 0:
                    e.flow += pushed
                    graph[e.to][e.rev].flow -= pushed
                    return pushed
        return 0

    return 0

