    # Two edges (a1, b1) and (a2, b2) cross if a1 < a2 < b1 < b2 or a2 < a1 < b2 < b1
    # (assuming all 4 endpoints are distinct)
    crossing = [[] for _ in range(m)]
    for i in range(m):
        a1, b1 = edges[i][0], edges[i][1]
        for j in range(i+1, m):
            a2, b2 = edges[j][0], edges[j][1]

            # Check if all 4 endpoints are distinct
            if len({a1, b1, a2, b2}) != 4:
                continue

            # Check crossing condition
            min1, max1 = min(a1, b1), max(a1, b1)
            min2, max2 = min(a2, b2), max(a2, b2)

            if (min1 < min2 < max1 < max2) or (min2 < min1 < max2 < max1):
                crossing[i].append(j)
                crossing[j].append(i)

    # 2-color the crossing graph using BFS
    color = [-1] * m

    possible = True
