def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    # Read cost matrix
    # Each line i has N-1 costs: costs for city i pairing with cities j where j != i
    # The costs are given in order: 1, 2, ..., i-1, i+1, ..., N
    costs = []
    for i in range(N):
        row = list(map(int, lines[i+1].split()))
        costs.append(row)

    # Build preferences for each city (sorted by cost, lower is better)
    prefs = []
    for i in range(N):
        city_costs = []
        for j in range(N):
            if i != j:
                # costs[i][j-1] is the cost for city i to pair with city j
                city_costs.append((j, costs[i][j-1]))
        # Sort by cost (lower is better)
        city_costs.sort(key=lambda x: x[1])
        prefs.append([c[0] for c in city_costs])

    # Find a stable roommate matching
    # For small inputs (N <= 11), we can enumerate all perfect matchings
    # For larger inputs, use Irving algorithm logic

    if N > 15:
        # Use Irving-like approach for larger N
        matching, partners = find_large_stable_matching(N, costs)
    else:
        # Enumerate perfect matchings for small N
        matching, partners = find_matchings(N)

    if matching is None:
        return "-1\n"

    # Output in the required format (1-indexed)
    partners_arr = [partners.get(i, -1) for i in range(N)]
    return '\n'.join(str(p + 1) for p in partners_arr)


def find_matchings(N, costs=None):
    """Enumerate all perfect matchings and find a stable one"""

    if costs is None:
        return None, None

    # Check if N is even (needed for perfect matching)
    if N % 2 != 0:
        return None, None

    # Build preference matrices (cost[i][j] = cost for city i to pair with city j, 0 if i==j)
    cost_matrix = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N - 1):
            cost_matrix[i][j + 1] = costs[i][j]

    # Generate all perfect matchings
    def generate_matchings():
        """Generate all ways to partition N cities into N/2 pairs"""
        if N == 0:
            yield []
            return

        cities = list(range(N))
        first = cities[0]
        for i in range(1, len(cities)):
            other = cities[i]
            rest = cities[1:i] + cities[i+1:]

            yield [(first, other)]
            for sub_match in generate_matchings(rest):
                yield [(first, other)] + sub_match

    # Check stability of a matching
    def is_stable(matching):
        for (a, b) in matching:
            # City a's partner is b
            # Check if a has a better partner available
            curr_cost_a = cost_matrix[a][b]

            for other in range(N):
                if other == b or other in partners:
                    continue  # Skip current partner or already processed

                # Is 'other' already matched with someone else?
                if partners.get(other) != a:
                    new_cost_a = cost_matrix[a][other]
                    # City a prefers 'other'
                    if new_cost_a < curr_cost_a:
                        # Does 'other' prefer 'a' over their current partner?
                        other_curr = partners.get(other)
                        other_cost_new = cost_matrix[other][a]
                        if other_curr is not None:
                            other_cost_curr = cost_matrix[other][other_curr]
                            if other_cost_new < other_cost_curr:
                                return False  # Blocking pair!
        return True

    # Try matchings
    for matching in generate_matchings():
        partners = {}
        for a, b in matching:
            partners[a] = b
            partners[b] = a

        if is_stable(matching):
            return matching, partners

    # No stable matching found
    # Try to find any stable configuration with heuristics
    return None, None


def find_large_stable_matching(N, costs):
    """Find stable matching using iterative approach for larger N"""

    # Build cost matrix
    cost_matrix = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N - 1):
            cost_matrix[i][j + 1] = costs[i][j]

    # Start with a greedy matching
    partner = [-1] * N
    for i in range(0, N, 2):
        partner[i] = i + 1
        partner[i + 1] = i

    # Iteratively improve through rotations
    improved = True
    while improved:
        improved = False
        for i in range(N):
            if partner[i] == -1:
                continue

            curr_partner = partner[i]
            curr_cost_i = cost_matrix[i][curr_partner]

            # Try to find a better match
            for j in range(N):
                if j == i:
                    continue

                if partner[j] != -1:
                    # Check rotation - can we swap?
                    j_partner = partner[j]

                    new_cost_i = cost_matrix[i][j]
                    new_cost_j = cost_matrix[j][i]

                    if new_cost_i < curr_cost_i and new_cost_j < cost_matrix[j][j_partner]:
                        partner[i] = j
                        partner[j] = i
                        partner[curr_partner] = -1
                        partner[j_partner] = -1
                        improved = True
                        break

    # Verify stability
    def is_stable(partners):
        for i in range(N):
            if partners[i] == -1:
                # Check if any unmatched city prefers i
                for j in range(N):
                    if partners[j] == -1 and j != i:
                        continue  # Need mutual preference check
        return True

    # Final verification would require more complex checks
    # Return best found matching
    partners_list = [partners[i] + 1 if partners[i] != -1 else -1 for i in range(N)]
    return matching, partners_list
