    if len(counts) == 1 and counts[0] > 1:
        return "0"

    # Simple inclusion-exclusion: 
    # For each group with size > 1, calculate arrangements where adjacent
    # elements from that group are treated as a single block

    from itertools import combinations

    def count_with_i_groups_adjacent(groups_to_adj):
        """Count permutations where elements from each specified group are adjacent."""
        remaining_N = n

        for g in groups_to_adj:
            count = groups[g]
            # These elements can be arranged within group: count!
            # And they form 1 block instead of count elements
            remaining_N -= count - 1

        # Total arrangements =remaining_N! * product of (count!) for each group
        result = fact[remaining_N] % MOD
        for g in groups_to_adj:
            result = result * math.factorial(groups[g]) % MOD

        return result

    total = 0
    # Enumerate all non-empty subsets of groups with size > 1
    groups_with_size_gt_1 = [g for g in groups if groups[g] > 1]

    for r in range(1, len(groups_with_size_gt_1) + 1):
        for subset in combinations(range(len(groups_with_size_gt_1)), r):
            groups_adj = [groups_with_size_gt_1[i] for i in subset]
            ways = count_with_i_groups_adjacent(groups_adj)

        if r % 2 == 1:
            total = (total - ways) % MOD
        else:
            total = (total + ways) % MOD

    return str(total % MOD)
