        B[i], B[max_row] = B[max_row], B[i]

        if abs(A[i][i]) < 1e-8:
            return None

        for j in range(i+1, n):
            f = A[j][i] / A[i][i]
            A[j][i:] = [A[j][k] - f*A[i][k] for k in range(i, n)]
            B[j] -= f * B[i]

    x = [0]*n
    for i in range(n-1, -1, -1):
