        for i in range(1, e + 1):
            dp[i] = 2

        for _ in range(r):
            new_dp = [0] * (e + 1)
            for i in range(e + 1):
                for j in range(i + 1):
                    new_dp[i] = (new_dp[i] + dp[j] * dp[i - j]) % MOD
            dp = new_dp

        return dp[e]

    def f_r(n, r):
        if n == 1:
            return 1
        factors = get_prime_factors(n)
        ans = 1
        for e in factors.values():
            ans = (ans * f_r_power(e, r)) % MOD
        return ans

    out = []
    for r, n in queries:
        out.append(str(f_r(n, r)))

