Looking at this problem, I need to find the minimum cost to make all elements of an array divisible by some common divisor d > 1 by either:
1. Removing one subsegment (cost m·a for m elements)
2. Changing elements by at most 1 (cost b per change)

The key insight is that after the final array is formed, all remaining elements must be divisible by some d. For each candidate d, I can calculate the minimum cost needed.

```python
def solution(input_str):
    n, a, b = map(int, input_str.split('\n')[0].split())
    arr = list(map(int, input_str.split('\n')[1].split()))

    def get_divisors(x):
        divs = set()
        for i in range(1, int(round(x**0.5)) + 1):
            if x % i == 0:
                divs.add(i)
                divs.add(x // i)
        return divs

    def check_d(d):
        def can_fix(val):
            if val % d == 0:
                return 0
            if (val - 1) % d == 0:
                return b
            if (val + 1) % d == 0:
                return b
            return float('inf')

        c0 = can_fix(arr[0])
        cn = can_fix(arr[n-1])
        if c0 == float('inf') or cn == float('inf'):
            return float('inf')

        first_bad = None
        last_bad = None
        cnt = 0

        for i in range(1, n-1):
            if can_fix(arr[i]) == float('inf'):
                if first_bad is None:
                    first_bad = i
                last_bad = i
                cnt += 1

        res = c0 + cn
        if first_bad is not None and last_bad is not None:
            idx = 0
            for i in range(first_bad, last_bad + 1):
                if can_fix(arr[i]) == float('inf'):
                    idx += 1
            res = min(res, idx * a)

        return res

    candidates = set()
    candidates.add(arr[0]-1)
    candidates.add(arr[0])
    candidates.add(arr[0]+1)
    candidates.add(arr[n-1]-1)
    candidates.add(arr[n-1])
    candidates.add(arr[n-1]+1)
    for x in arr[:min(10, n)]:
        for d in get_divisors(x):
            candidates.add(d)

    ans = float('inf')
    for d in candidates:
        if d > 1:
            res = check_d(d)
            if res != float('inf'):
                ans = min(ans, res)

    return str(ans)
